    const n = big ? 2000 : r.int(1, 7);
    const side = Array.from({ length: n }, () => r.int(0, 1));
    const bip = big || r.bool();
    const want = big ? 10000 : r.int(0, Math.min(8, (n * (n - 1)) / 2));
    const seen = new Set(), edges = [];
    for (let t = 0; edges.length < want && t < 50000; t++) {
      const a = r.int(1, n), b = r.int(1, n);
      if (a === b || (bip && side[a - 1] === side[b - 1])) continue;
      const key = Math.min(a, b) * 5000 + Math.max(a, b);
      if (seen.has(key)) continue;
      seen.add(key);
      edges.push([a, b]);
    }
    return [n, edges];
  }

